In the zero-displacement case, 
a CVGS  $\rho_\sigma$ is a state with a Wigner function of the form \cite{Weedbrook12,Ferraro05,Wang07,Adesso14,Navarrete22}
\begin{equation}
\!\!\!\begin{array}{l}
\mathcal{W}_{\!\varrho_\sigma} (q,p)\!=\!\frac{2}{h \sqrt{\det\sigma}}\, {\rm exp}\left\{\!-\frac{2\pi }{h} {\scriptsize (\,q\ \ p\, )}{\scriptsize \left(\!\!\!
\begin{array}{ll}
\sigma_{11} & \!\sigma_{12}\\
\sigma_{12} & \!\sigma_{22}
\end{array}\!\!\!\right)^{\!\!-1} \!\!\!\left(\!\!
\begin{array}{c}
q\\
p
\end{array}\!\!\right)}\!\right\},
\end{array}
\end{equation}
where  the covariance matrix
\begin{equation}\label{sigcon}
\sigma\!=\!{\scriptsize \left(\!\!
\begin{array}{cc}
\sigma_{11} & \sigma_{12}\\
\sigma_{12} & \sigma_{22}
\end{array}\!\!\right)},\quad \mbox{satisfying}\quad \sigma \!+\!{\rm i} {\scriptsize \left(\!\!
\begin{array}{cc}
0 & 1\\
-1 & 0
\end{array}\!\!\right)}\!\geq \!0,
\end{equation}
is a real $2\!\times\!2$ symmetric positive-definite matrix.

The {\it $\ell_1$-norm of coherence} of a state $\varrho$ with respect to the frame $\mathcal{F}=\{ \, |\varphi _1\rangle,\, |\varphi _2\rangle,\, ...\, |\varphi _m\rangle\, \}$ is
\begin{equation} \label{framecoherence}    
\mathcal{C}_\mathcal{F}(\varrho)=\frac{d^2}{2m^2}\sum\limits_{j,k=1}^m|\langle\varphi_j|\varrho|\varphi_k\rangle|.
\end{equation}

\\

From (\ref{rhosigma}), we get \
$
\langle\alpha,\beta|\varrho_\sigma|\gamma,\delta\rangle=
\int\limits_{\mathbb{R}^2}\mathcal{W}_{\!\varrho_\sigma} (q,p)\, \langle\alpha,\beta|\Pi(q,p)|\gamma,\delta\rangle dqdp. 
$\ \ 
By using  (\ref{coherentst}) and (\ref{Piqp}), we obtain
\[
\begin{array}{l}
\langle\alpha,\beta|\Pi(q,p)|\gamma,\delta\rangle=\sqrt{\frac{2}{h}}\ \ 
\mathrm{e}^{\frac{\pi \mathrm{i}}{h}(\alpha \beta-\gamma \delta)}
\int\limits_{-\infty}^\infty\mathrm{e}^{-\frac{2\pi \mathrm{i}}{h}\beta x}\ \ 
\mathrm{e}^{-\frac{\pi}{h}(x-\alpha)^2}\mathrm{e}^{\frac{4 \pi \mathrm{i}}{h}p(x-q)}\ \ 
\mathrm{e}^{\frac{2\pi \mathrm{i}}{h}\delta(2q-x)}\ \ \mathrm{e}^{-\frac{\pi}{h}(2q-x-\gamma)^2}dx
{}\\[4mm]

\qquad \qquad \quad   =\sqrt{\frac{2}{h}}\,
\mathrm{e}^{-\frac{\pi}{h}(\alpha^2+\gamma^2- \mathrm{i}\alpha \beta+\mathrm{i}\gamma \delta)} \ 
\mathrm{e}^{-\frac{4\pi}{h}(q^2+\mathrm{i}pq-\gamma q-\mathrm{i}\delta q)} \!\!\int\limits_{-\infty}^\infty\!\!\mathrm{e}^{-\frac{2\pi}{h}[x-\frac{1}{2}(\alpha -\mathrm{i}\beta -\gamma -\mathrm{i}\delta+2q+2\mathrm{i}p)]^2}dx \ 
\mathrm{e}^{\frac{\pi}{2h}(\alpha -\mathrm{i}\beta -\gamma -\mathrm{i}\delta+2q+2\mathrm{i}p)^2}\\[4mm]

\qquad \qquad \quad  =\sqrt{\frac{2}{h}}\,
\mathrm{e}^{-\frac{\pi}{h}(\alpha^2+\gamma^2- \mathrm{i}\alpha \beta+\mathrm{i}\gamma \delta)}\ \ 
\mathrm{e}^{-\frac{4\pi}{h}(q^2+\mathrm{i}pq-\gamma q-\mathrm{i}\delta q)}\  \sqrt{\frac{h}{2\pi}}\,\sqrt{\pi}\ 
\mathrm{e}^{\frac{\pi}{2h}(\alpha -\mathrm{i}\beta -\gamma -\mathrm{i}\delta+2q+2\mathrm{i}p)^2}\\[4mm]

\qquad \qquad \quad   =
\mathrm{e}^{-\frac{\pi}{2h}(\alpha+\gamma)^2}\ \ 
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}\ \ 
\mathrm{e}^{-\frac{\pi\mathrm{i}}{h}(\alpha\delta-\beta\gamma)}
\ \ 
\mathrm{e}^{-\frac{2\pi}{h}[q^2-(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta)q]}\ \ 
\mathrm{e}^{-\frac{2\pi}{h}[p^2-(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)p]}\\[4mm]
\end{array}
\]

By denoting \, $
\left(\!\!\!
\begin{array}{ll}
a & c\\
c & b
\end{array}\!\!\!\right)\!=\!
\left(\!\!\!
\begin{array}{ll}
\sigma_{11} & \!\sigma_{12}\\
\sigma_{12} & \!\sigma_{22}
\end{array}\!\!\!\right)^{\!\!-1}\!\!\!\!\!=\frac{1}{\mathrm{det}\, \sigma}
\left(\!\!\!
\begin{array}{rr}
\sigma_{22} & \!-\sigma_{12}\\
-\sigma_{12} & \!\sigma_{11}
\end{array}\!\!\!\right)
$ \  we obtain \  
$\mathcal{W}_{\!\varrho_\sigma} (q,p)\!=\!\frac{2}{h \sqrt{\det\sigma}}\, \mathrm{e}^{-\frac{2\pi}{h}(aq^2+2cqp+bp^2)}$\ \ and
\[
\begin{array}{l}
|\langle\alpha,\beta|\varrho_\sigma|\gamma,\delta\rangle|=
\left|\int\limits_{\mathbb{R}^2}\mathcal{W}_{\!\varrho_\sigma} (q,p)\, \langle\alpha,\beta|\Pi(q,p)|\gamma,\delta\rangle dqdp\right|\\[2mm]

\qquad \qquad  =\frac{2}{h \sqrt{\det\sigma}}\, 
\mathrm{e}^{-\frac{\pi}{2h}(\alpha+\gamma)^2}\, 
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}\, 
\left|\mathrm{e}^{-\frac{\pi\mathrm{i}}{h}(\alpha\delta-\beta\gamma)}
\int\limits_{\mathbb{R}^2}\mathrm{e}^{-\frac{2\pi}{h}[(a+1)q^2-(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta-2cp)q]}dq\, 
\mathrm{e}^{-\frac{2\pi}{h}[(b+1)p^2-(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)p]}dp\right|\\[4mm]

\qquad \qquad  =\frac{2}{h \sqrt{\det\sigma}}\, 
\mathrm{e}^{-\frac{\pi}{2h}(\alpha+\gamma)^2}\, 
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}\, 
\left|\int\limits_{\mathbb{R}^2}\mathrm{e}^{-\frac{2\pi}{h}[\sqrt{a+1}\, q-\frac{1}{2\sqrt{a+1}}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta-2cp)]^2}dq\right.\\
\qquad \qquad \qquad \qquad \qquad \qquad \qquad\qquad 
\qquad \qquad \qquad \quad \
\left.\mathrm{e}^{\frac{2\pi}{h}\frac{1}{4(a+1)}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta-2cp)^2}\ 
\mathrm{e}^{-\frac{2\pi}{h}[(b+1)p^2-(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)p]}dp\right|
\end{array}
\]

\[
\begin{array}{l}
\qquad \qquad  =\frac{2}{h \sqrt{\det\sigma}}\ 
\mathrm{e}^{-\frac{\pi}{2h}(\alpha+\gamma)^2}\ \ 
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2} \
\sqrt{\frac{h}{2\pi}}\frac{\sqrt{\pi}}{\sqrt{a+1}} \
\left| \mathrm{e}^{\frac{\pi}{2h}\frac{1}{a+1}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta)^2} \right|
\\[3mm]
\qquad \qquad \qquad \qquad \qquad \qquad 
\qquad \qquad \qquad \quad \
\left|\int\limits_{-\infty}^\infty
\mathrm{e}^{\frac{2\pi}{h}\frac{c^2}{a+1}p^2}\ \ 
\mathrm{e}^{-\frac{2\pi}{h}\frac{c}{a+1}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta)p}\ \ 
\mathrm{e}^{-\frac{2\pi}{h}[(b+1)p^2-(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)p]}dp\right|\\[2mm]

\qquad \qquad   =
\sqrt{\frac{2}{a+1}}\frac{1}{\sqrt{h\,\det\sigma}}\, 
\mathrm{e}^{-\frac{\pi}{2h}(\alpha+\gamma)^2}
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}
\mathrm{e}^{\frac{\pi}{2h}\frac{1}{a+1}(\alpha +\gamma)^2} 
\mathrm{e}^{-\frac{\pi}{2h}\frac{1}{a+1}(\beta -\delta)^2} 
\\
\qquad \qquad \qquad \qquad \qquad \qquad 
\qquad \qquad \qquad \quad \
\left|\int\limits_{\infty}^\infty
\mathrm{e}^{-\frac{2\pi}{h}(b+1-\frac{c^2}{a+1})p^2+\frac{2\pi}{h}
[(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)-\frac{c}{a+1}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta)]p}
dp\right|\\[2mm]

\qquad \qquad   =
\sqrt{\frac{2}{a+1}}\frac{1}{\sqrt{h\,\det\sigma}}\, 
\mathrm{e}^{-\frac{\pi}{2h}\frac{a}{a+1}(\alpha+\gamma)^2}
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}
\mathrm{e}^{-\frac{\pi}{2h}\frac{1}{a+1}(\beta -\delta)^2} 
\\
\qquad \qquad \qquad \qquad\qquad \qquad\left|\int\limits_{\infty}^\infty
\mathrm{e}^{-\frac{2\pi}{h}\left\{\sqrt{\frac{(a+1)(b+1)-c^2}{a+1}}p
-\frac{1}{2}\sqrt{\frac{a+1}{(a+1)(b+1)-c^2}}
\left[(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)-\frac{c}{a+1}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta)\right]\right\}^2}
dp\right|\\[4mm]
\qquad \qquad \qquad \qquad\qquad \qquad \qquad \qquad\qquad\qquad \qquad \qquad
\left|
\mathrm{e}^{\frac{\pi}{2h}\frac{a+1}{(a+1)(b+1)-c^2}
\left[(\mathrm{i}\alpha+\beta -\mathrm{i}\gamma+\delta)-\frac{c}{a+1}(\alpha-\mathrm{i}\beta +\gamma+\mathrm{i}\delta)\right]^2}
\right|\\[2mm]

\qquad \qquad   =
\sqrt{\frac{2}{a+1}}\frac{1}{\sqrt{h\,\det\sigma}}\, 
\mathrm{e}^{-\frac{\pi}{2h}\frac{a}{a+1}(\alpha+\gamma)^2}
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}
\mathrm{e}^{-\frac{\pi}{2h}\frac{1}{a+1}(\beta -\delta)^2} 
\sqrt{\frac{h}{2\pi}}\sqrt{\frac{a+1}{(a+1)(b+1)-c^2}} \, \sqrt{\pi}
\\[3mm]
\qquad \qquad \qquad \qquad\qquad \qquad \qquad \qquad \ \ 
\mathrm{e}^{-\frac{\pi}{2h}\frac{a+1}{(a+1)(b+1)-c^2}
\left[\alpha-\gamma+\frac{c}{a+1}(\beta-\delta)\right]^2} \
\mathrm{e}^{\frac{\pi}{2h}\frac{a+1}{(a+1)(b+1)-c^2}
\left[\beta +\delta-\frac{c}{a+1}(\alpha +\gamma)\right]^2}\\[2mm]

\qquad \qquad   =
\frac{1}{\sqrt{\det\sigma}}\frac{1}{\sqrt{(a+1)(b+1)-c^2}}\, 
\mathrm{e}^{-\frac{\pi}{2h}\frac{a}{a+1}(\alpha+\gamma)^2}
\mathrm{e}^{-\frac{\pi}{2h}(\beta+\delta)^2}
\mathrm{e}^{-\frac{\pi}{2h}\frac{1}{a+1}(\beta -\delta)^2} 
\\[2mm]
\qquad \qquad \qquad \qquad\qquad \qquad \qquad\qquad
\mathrm{e}^{-\frac{\pi}{2h} \frac{a+1}{(a+1)(b+1)-c^2}
\left[\alpha-\gamma+\frac{c}{a+1}(\beta-\delta)\right]^2} \
\mathrm{e}^{\frac{\pi}{2h} \frac{a+1}{(a+1)(b+1)-c^2}
\left[\beta +\delta-\frac{c}{a+1}(\alpha +\gamma)\right]^2}
\end{array}
\]




By denoting $\eta\!=\!(a\!+\!1)(b\!+\!1)-c^2$ and using the change of variables $x\!=\!\alpha\!+\!\gamma$, $y\!=\!\beta\!+\!\delta$,
$u\!=\!\alpha\!-\!\gamma$, $v\!=\!\beta\!-\!\delta$, we get
\[
\begin{array}{l}
\int\limits_{\mathbb{R}^4}|\langle \alpha,\beta|\varrho_\sigma|\gamma,\delta\rangle|d\alpha d\beta d\gamma d\delta =\\[3mm]
\qquad \qquad =\frac{1}{4\sqrt{\det\sigma}}\frac{1}{\sqrt{\eta}}\, 
\int\limits_{\mathbb{R}^4}\mathrm{e}^{-\frac{\pi}{2h}\frac{a}{a+1}x^2}
\mathrm{e}^{-\frac{\pi}{2h}y^2}
\mathrm{e}^{-\frac{\pi}{2h}\frac{1}{a+1}v^2} 
\mathrm{e}^{-\frac{\pi}{2h} \frac{a+1}{\eta}
\left[u+\frac{c}{a+1}v\right]^2} 
\mathrm{e}^{\frac{\pi}{2h} \frac{a+1}{\eta}
\left[y-\frac{c}{a+1}x\right]^2}dxdydudv\\[2mm]

\qquad \qquad =\frac{1}{4\sqrt{\det\sigma}}\frac{1}{\sqrt{\eta}}\, 
\int\limits_{\mathbb{R}^2}
\mathrm{e}^{-\frac{\pi}{2h} \frac{a+1}{\eta}
\left[u+\frac{c}{a+1}v\right]^2}\mathrm{e}^{-\frac{\pi}{2h}\frac{1}{a+1}v^2}  dudv\
\int\limits_{\mathbb{R}^2}\mathrm{e}^{-\frac{\pi}{2h} \frac{a+1}{\eta}
\left[y-\frac{c}{a+1}x\right]^2}\mathrm{e}^{-\frac{\pi}{2h}\frac{a}{a+1}x^2}\mathrm{e}^{-\frac{\pi}{2h}y^2}dxdy\\[2mm]

\qquad \qquad =\frac{1}{4\sqrt{\det\sigma}}\frac{1}{\sqrt{\eta}}\, 
\sqrt{\frac{2h}{\pi}}\frac{\sqrt{\eta}}{\sqrt{a+1}} \sqrt{\pi}\ 
\sqrt{\frac{2h}{\pi}}\sqrt{a+1} \sqrt{\pi}\\[3mm]

\qquad \qquad \qquad \qquad\int\limits_{\mathbb{R}^2}\mathrm{e}^{-\frac{\pi}{2h} \left[\sqrt{\frac{ab+b-c^2}{\eta}}y+\frac{c}{\eta}
\sqrt{\frac{\eta}{ab+b-c^2}}x\right]^2}dy \ 
\mathrm{e}^{\frac{\pi}{2h}\frac{c^2}{\eta(a+1)}x^2}\mathrm{e}^{-\frac{\pi}{2h}\frac{a}{a+1}x^2}\mathrm{e}^{\frac{\pi}{2h}\frac{c^2}{\eta^2}\frac{\eta}{ab+b-c^2}x^2}dx\\[2mm]

\qquad \qquad =\frac{h}{2\sqrt{\det\sigma}}
\int\limits_{-\infty}^\infty\mathrm{e}^{-\frac{\pi}{2h} \left[\sqrt{\frac{ab+b-c^2}{\eta}}y+\frac{c}{\eta}
\sqrt{\frac{\eta}{ab+b-c^2}}x\right]^2}dy \ 
\int\limits_{-\infty}^\infty
\mathrm{e}^{-\frac{\pi}{2h}\frac{ab-c^2}{ab+b-c^2}x^2}dx\\[2mm]

\qquad \qquad =\frac{h}{2\sqrt{\det\sigma}}
\sqrt{\frac{2h}{\pi}}\frac{\sqrt{\eta}}{\sqrt{ab+b-c^2}} \sqrt{\pi}\ 
\int\limits_{-\infty}^\infty
\mathrm{e}^{-\frac{\pi}{2h}\frac{ab-c^2}{ab+b-c^2}x^2}dx\\[2mm]

\qquad \qquad =\frac{h\sqrt{h}}{\sqrt{2\, \det\sigma}}
\frac{\sqrt{\eta}}{\sqrt{ab+b-c^2}}\ 
\int\limits_{-\infty}^\infty
\mathrm{e}^{-\frac{\pi}{2h}\frac{ab-c^2}{ab+b-c^2}x^2}dx=\frac{h\sqrt{h}}{\sqrt{2\, \det\sigma}}
\frac{\sqrt{\eta}}{\sqrt{ab+b-c^2}}\ \sqrt{\frac{2h}{\pi}}\frac{\sqrt{ab+b-c^2}}{\sqrt{ab-c^2}} \sqrt{\pi}\ 
\\[2mm]

\qquad \qquad =\frac{h^2}{\sqrt{\det\sigma}}
\frac{\sqrt{\eta}}{\sqrt{ab-c^2}}  
 =\frac{h^2}{\sqrt{\det\sigma}}
\frac{\sqrt{ab+a+b+1-c^2}}{\sqrt{ab-c^2}}  
 =\frac{h^2}{\sqrt{\det\sigma}}
\sqrt{ \det\sigma +\mathrm{tr}\, \sigma +1}.
\end{array}
\]

